from pathlib import Path
import json,re,html
root=Path(__file__).resolve().parents[1]
out=root/'web/public/deck'
vault=re.search(r"DEMO_VAULT = '([^']+)'",(root/'web/lib/config.ts').read_text())[1]
explorer='https://devnet.xrpl.org/transactions/'
def link(label,hash): return f'<a href="{explorer}{hash}" target="_blank" rel="noreferrer">{label}</a>'
loan=link('Origination · EDF10740','EDF107402242DB11C46B0DB87CDD97704CBB851840A3A49CC0BD31DD14B61C41')
default=link('Covered default · 95AD6692','95AD6692375BFD184155472FA105571BA9C9A836B221BB36F11CAA4F699C81D4')
slides=[
 dict(time='0:00–0:15',tag='The opportunity',title='Good assets.<br />Put to <em>work.</em>',body='<p class="lede">Securities lending, native on the XRP Ledger.</p><p>Tokenised securities give holders ownership.<br />Patapim gives them a way to lend those securities, for a fee.</p><div class="chips"><span>Track 2 / Closed-ended vault</span><span>Loaded / XLS-65 + XLS-66</span></div>',note='Tokenised treasuries and money market funds need more than issuance. We built agency securities lending: holders lend securities through an agent, for a fee. This is a Devnet prototype with a fictitious security, not a production fund.',source='README.md · Why / The trade'),
 dict(time='0:15–0:30',tag='The product',title='A market with an agent<br /><em>on the hook.</em>',body='<div class="flow"><div><small>01 / SUPPLY</small><h3>Eligible holders</h3><p>Deposit securities.<br />Receive vault shares.</p></div><div class="highlight"><small>02 / POOL</small><h3>Fixed-term vault</h3><p>Native XRPL objects.<br />A defined lending window.</p></div><div><small>03 / DEMAND</small><h3>Borrowers</h3><p>Borrow securities.<br />Return them plus a fee.</p></div></div><p class="callout">The lending agent posts first-loss capital in the same security.</p>',note='The asset in the vault is the security itself. The agent owns the vault and loan broker, checks borrower eligibility and posts cover. XRP collateral is a separate bilateral escrow; do not describe escrow and default settlement as one atomic transaction.',source='README.md · The trade / The other primitives'),
 dict(time='0:30–1:30',tag='Demo / Subscription',title='Eligibility the ledger<br /><em>actually enforces.</em>',body=f'<div class="split"><div><p class="lede">One eligible deposit.<br />One refused deposit.</p><p>Credentials and a Permissioned Domain control access to the lender pool.</p><a class="cta" href="/vault/{vault}" target="_blank" rel="noreferrer">Open live vault</a></div><div class="results"><div><span>Eligible holder / VaultDeposit</span><strong>tesSUCCESS</strong></div><div><span>Non-member / VaultDeposit</span><strong class="danger">tecNO_AUTH</strong></div></div></div>',note='Switch to the live vault provisioned by the protocol operator. The link uses DEMO_VAULT from lib/config.ts at deck-generation time; use the fresh vault URL when rehearsing. Trigger deposits from the existing operator script. The dashboard is read-only and does not submit transactions. If the phase walk is not the live arc, open verified transaction links.',source=link('Eligible · CE5C7E59','CE5C7E595B0D9761B10BE9114AEF38597A03A9620A1590EE7DEC56528B47D06C')+' · '+link('Refused · D4C93863','D4C938639DD005D8B4AD6ADB06425AC6E15047C15C02B80386AAA2E07C3DBC88')),
 dict(time='1:30–2:00',tag='Demo / Phase boundary',title='The calendar is<br /><em>a protocol rule.</em>',body='<div class="flow"><div><small>01 / SUBSCRIPTION</small><h3>Deposit</h3><p>LoanSet refused:<br /><code>tecTOO_SOON</code></p></div><div class="highlight"><small>02 / INVESTMENT</small><h3>Lend</h3><p>VaultDeposit refused:<br /><code>tecEXPIRED</code></p></div><div><small>03 / REDEMPTION</small><h3>Withdraw</h3><p>LoanSet refused:<br /><code>tecEXPIRED</code></p></div></div><p class="callout">Watch the phase and refusal list change on a fresh ledger read.</p>',note='The phase comes from immutable vault dates compared with the ledger close time. The page refreshes every ten seconds and never advances the phase from the browser clock. Show the deposit rejection at the phase boundary. The complete phase walk and default arc cannot both run live in four minutes: the minimum investment period is 180 seconds. Choose one and use verified evidence for the other.',source=link('Closed subscription · 7B9D16FA','7B9D16FA25DA3F54B7B3A13A63C21AB06775346264A4D1EC12228EBCFD709291')+' · docs/PLAN.md'),
 dict(time='2:00–2:30',tag='Demo / Origination',title='Two signatures.<br /><em>One loan.</em>',body='<div class="signature"><span>Lending agent</span><b>+</b><span>Borrower</span><b>=</b><strong>LoanSet</strong></div><div class="flow"><div><small>THE ASSET</small><h3>MPT security</h3><p>Delivered to the borrower.</p></div><div><small>THE CAPITAL</small><h3>First-loss cover</h3><p>Agent-funded, in securities.</p></div><div><small>THE COLLATERAL</small><h3>XRP Escrow</h3><p>Managed bilaterally.</p></div></div>',note='Show the co-signed origination transaction and the resulting loan book row. The browser reads the ledger server-side; the protocol operator submits the transaction. The required beta SDK needs our counterparty-signing workaround, described later.',source=loan+' · README.md / The trade'),
 dict(time='2:30–3:15',tag='Verified default / 100% cover rate',title='The borrower defaults.<br /><em>The agent pays.</em>',body='<div class="split"><div><div class="big">2,000,000</div><p>Securities absorbed by agent cover.</p><p>Cover falls from 2,500,000 to 500,000.<br />Vault assets after default: 5,000,000.</p></div><table><thead><tr><th>State</th><th>Net share price</th></tr></thead><tbody><tr><td>Loan drawn</td><td>1.00</td></tr><tr><td>Impaired</td><td>0.60</td></tr><tr><td>Default settled</td><td class="green">1.00</td></tr></tbody></table></div><p class="formula">Net share price = (AssetsTotal − LossUnrealized) / OutstandingAmount</p>',note='Use the fully covered default arc. During impairment, the correct net price is 0.60: (5,000,000 − 2,000,000) / 5,000,000. The historical evidence file records the old gross-ratio price of 1.00 at that step; the net figure here is recomputed from its raw fields, consistent with lib/ledger.ts and the developer report. After default, cover restores net price to 1.00. Do not say that the price never moves. At a 10% cover rate, the same default ends at 0.64; the configured rate, not merely the posted balance, decides absorption.',source=default+' · docs/evidence/default-arc-cover100000.json'),
 dict(time='3:15–3:35',tag='Developer experience / Three fixes',title='What building it<br /><em>made visible.</em>',body='<div class="findings"><div><span>01</span><h3>The mandated beta cannot co-sign.</h3><p>Backport the counterparty hash prefix fix.</p></div><div><span>02</span><h3>No SDK release covers both halves.</h3><p>Ship V1.1 types and correct signing together.</p></div><div><span>03</span><h3>Same amendments. Different network rules.</h3><p>Publish effective protocol versions per network.</p></div></div>',note='Keep this to twenty seconds. The mandated beta has closed-ended types but uses the wrong signing prefix. Stable signs correctly but lacks the V1.1 types. Both hackathon networks advertise the same amendments while enforcing different rules. These are observed development findings in the report; do not change networks in the demo.',source='<a href="https://github.com/gamween/patapim/blob/main/DEVELOPER-REPORT.md" target="_blank" rel="noreferrer">DEVELOPER-REPORT.md · Findings 1–3</a>'),
 dict(time='3:35–3:45',tag='Protocol proposal',title='A fixed end date needs<br /><em>a way to recall.</em>',body='<p class="lede">A closed-ended vault protects the calendar.<br />An unpaid loan can still leave it illiquid at redemption.</p><div class="proposal"><small>PROPOSED / NOT IMPLEMENTED</small><strong>tfLoanCall</strong><p>Let the agent call a loan before term, against the borrower’s grace period.</p></div>',note='This is a proposal for LendingProtocolV1_2, not a transaction the prototype can execute. Close the findings with a specific protocol ask: an early recall path so an agent can manage the vault’s maturity.',source='DEVELOPER-REPORT.md · What the protocol made hard'),
 dict(time='3:45–4:00',tag='Contribution back',title='A working trade.<br /><em>A useful contribution.</em>',body='<div class="split"><div><p class="lede">Loan and LoanBroker IDs should be searchable.</p><p>Our Explorer pull request routes these identifiers to their vault using the existing ledger-entry lookup.</p><a class="cta" href="https://github.com/ripple/explorer/pull/1342" target="_blank" rel="noreferrer">ripple/explorer #1342</a></div><div class="endmark">patapim<small>Securities lending,<br />native on the XRP Ledger.</small></div></div>',note='The Explorer PR was verified open when this deck was prepared; do not call it merged. Close on the actual contribution and invite the jury to inspect the live vault, transaction evidence and developer report. Submission: Sunday 13 September 2026 at 13:00 CEST; code freeze 12:30. Rehearse with a fresh vault and retain a recorded run for network failure.',source='ripple/explorer#1342 · README.md · DEVELOPER-REPORT.md'),
]
css='''@font-face{font-family:DM;src:url('../fonts/dm-mono-regular.ttf')} :root{--bg:#101610;--fg:#f4f5ee;--muted:#abb8a5;--line:#354332;--green:#b8ff79;--danger:#ffaba1;--surface:#1b2518;--ink:#15200d}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:18px/1.5 Arial,Helvetica,sans-serif;font-variant-numeric:tabular-nums}a{color:inherit;text-underline-offset:4px}button,a:focus-visible{outline-offset:5px}button:focus-visible,a:focus-visible{outline:2px solid var(--green)}.slide{padding:5vh 6vw 8vh;min-height:100svh;display:flex;flex-direction:column}.slide[hidden]{display:none}.topline{display:flex;justify-content:space-between;gap:20px;font:11px DM,monospace;color:var(--muted);text-transform:uppercase;letter-spacing:.06em}h1{font-size:clamp(42px,5.8vw,90px);line-height:1.02;letter-spacing:-.06em;font-weight:400;margin:5vh 0 4vh;max-width:23ch}em{font-style:normal;color:var(--green)}p{margin:14px 0;max-width:60ch;color:var(--muted)}.lede{font-size:clamp(22px,2.2vw,34px);line-height:1.3;color:var(--fg)}h3{font-size:clamp(20px,2vw,30px);font-weight:400;line-height:1.2;letter-spacing:-.03em;margin:20px 0 12px}small,code,.chips,.formula{font:11px/1.6 DM,monospace}small{color:var(--muted)}.chips{display:flex;flex-wrap:wrap;gap:16px;margin-top:35px}.chips span{padding:12px 18px;border:1px solid var(--line);border-radius:40px}.flow{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.flow>div{padding:24px;border:1px solid var(--line);border-radius:8px}.flow p{font-size:16px}.flow .highlight{border-color:var(--green);background:var(--surface)}.highlight h3{color:var(--green)}.callout{margin-top:30px;color:var(--green);font-size:23px}.split{display:grid;grid-template-columns:1fr 1fr;gap:6vw;align-items:center}.results>div{padding:25px 0;border-top:1px solid var(--line)}.results span{font:12px DM,monospace;color:var(--muted);display:block}.results strong{font:28px DM,monospace;color:var(--green);display:block;margin-top:15px}.results .danger{color:var(--danger)}.cta{display:inline-block;margin-top:18px;padding:14px 24px;background:var(--green);color:var(--ink);text-decoration:none;border-radius:40px;font-size:15px}.signature{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:25px 0 35px;font-size:clamp(20px,2.4vw,36px)}.signature b{font-weight:400;color:var(--muted)}.signature strong{color:var(--green);font-weight:400}.big{font-size:clamp(44px,5.5vw,82px);letter-spacing:-.06em;color:var(--green)}table{border-collapse:collapse;width:100%;font-size:22px}th{font:11px DM,monospace;color:var(--muted);text-transform:uppercase}th,td{padding:20px 0;border-bottom:1px solid var(--line);text-align:left}td:last-child,th:last-child{text-align:right}.green{color:var(--green)}.formula{margin-top:30px}.findings>div{display:grid;grid-template-columns:45px 1.3fr 1fr;align-items:center;gap:25px;border-top:1px solid var(--line);padding:20px 0}.findings span{font:13px DM,monospace;color:var(--green)}.findings h3{margin:0;font-size:25px}.findings p{font-size:16px;margin:0}.proposal{background:var(--surface);padding:24px 32px;border:1px solid var(--line);border-radius:8px;margin-top:24px}.proposal strong{display:block;color:var(--green);font:42px DM,monospace;margin-top:12px}.proposal p{margin-bottom:0}.endmark{font-size:clamp(65px,8vw,120px);font-weight:700;letter-spacing:-.07em;color:var(--green)}.endmark small{display:block;letter-spacing:0;font-size:14px;color:var(--fg)}.source{margin-top:auto;padding-top:30px;color:var(--muted);font:10px/1.5 DM,monospace}.source a{display:inline-block}.notes{border-top:1px solid var(--line);padding-top:20px;color:var(--green);font-size:15px}.controls{position:fixed;bottom:0;left:0;right:0;display:flex;gap:12px;align-items:center;justify-content:center;background:var(--bg);border-top:1px solid var(--line);padding:9px 15px}.controls button,.controls a{font:11px DM,monospace;color:var(--fg);background:none;border:1px solid var(--line);border-radius:30px;padding:8px 14px;text-decoration:none;cursor:pointer}.controls button:disabled{opacity:.4;cursor:default}.controls span{font:11px DM,monospace;color:var(--muted);min-width:65px;text-align:center}.progress{height:2px;background:var(--green);position:fixed;bottom:51px;left:0}.notes[hidden]{display:none}@media(max-width:700px){.slide{padding:28px 24px 100px}.topline{font-size:9px}h1{margin:40px 0 30px;font-size:43px}.split,.flow{grid-template-columns:1fr;gap:20px}.signature{flex-wrap:wrap;justify-content:flex-start}.findings>div{grid-template-columns:25px 1fr;gap:12px}.findings p{grid-column:2}.controls{gap:5px;flex-wrap:wrap}.controls button,.controls a{padding:8px;font-size:9px}.controls span{min-width:45px}.progress{display:none}.source{padding-top:35px}.callout{font-size:20px}table{font-size:18px}.big{font-size:52px}}@page{size:1280px 720px;margin:0}@media print{body{print-color-adjust:exact;-webkit-print-color-adjust:exact}.slide,.slide[hidden]{display:flex!important;width:1280px;height:720px;min-height:0;padding:38px 64px;break-after:page;overflow:hidden}.slide:last-child{break-after:auto}h1{font-size:70px;margin:32px 0}.controls,.progress,.notes{display:none!important}.source{padding-top:20px}.topline{font-size:11px}.flow p{font-size:16px}}'''
parts=[]
for i,s in enumerate(slides):
    parts.append(f'<section class="slide" id="slide-{i+1}" aria-label="Slide {i+1} of 9" {"hidden" if i else ""}><div class="topline"><span>patapim / {s["tag"]}</span><span>{s["time"]} · Paris 2026</span></div><h1>{s["title"]}</h1><div>{s["body"]}</div><div class="source">{s["source"]}</div><aside class="notes" hidden><strong>Speaker notes</strong><p>{html.escape(s["note"])}</p></aside></section>')
js='''const slides=[...document.querySelectorAll('.slide')];let current=0;let notes=false;const prev=document.querySelector('#prev'),next=document.querySelector('#next');function show(index){current=Math.max(0,Math.min(slides.length-1,index));slides.forEach((s,i)=>{s.hidden=i!==current;s.querySelector('.notes').hidden=!notes});document.querySelector('#count').textContent=`${String(current+1).padStart(2,'0')} / 09`;document.querySelector('.progress').style.width=((current+1)/9*100)+'%';prev.disabled=current===0;next.disabled=current===8;history.replaceState(null,'','#'+(current+1));window.scrollTo(0,0)}function toggleNotes(){notes=!notes;document.querySelector('#notes').setAttribute('aria-pressed',String(notes));show(current)}prev.onclick=()=>show(current-1);next.onclick=()=>show(current+1);document.querySelector('#notes').onclick=toggleNotes;document.querySelector('#print').onclick=()=>window.print();document.addEventListener('keydown',e=>{if(e.altKey||e.ctrlKey||e.metaKey||/INPUT|TEXTAREA|BUTTON|A/.test(e.target.tagName))return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(current+1)}else if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(current-1)}else if(e.key==='Home'){e.preventDefault();show(0)}else if(e.key==='End'){e.preventDefault();show(8)}else if(e.key.toLowerCase()==='n'){toggleNotes()}});show((Number(location.hash.slice(1))||1)-1);'''
(out/'index.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Patapim — Jury deck</title><style>'+css+'</style></head><body><main>'+''.join(parts)+'</main><div class="progress" aria-hidden="true"></div><nav class="controls" aria-label="Presentation controls"><button id="prev">Previous</button><span id="count" role="status">01 / 09</span><button id="next">Next</button><button id="notes" aria-pressed="false">Notes</button><button id="print">Print / PDF</button><a href="/">Website</a></nav><script>'+js+'</script></body></html>')
md=['# Patapim — four-minute jury deck','', 'Nine slides. Open `/deck/index.html` in the web app. Arrow keys / Page Up / Page Down / Space navigate; Home and End jump; N toggles notes. Print / PDF exports all slides without notes. A PDF is included as `docs/PATAPIM-DECK.pdf`.','', 'Source of product and findings: `README.md`, `DEVELOPER-REPORT.md`, `docs/PLAN.md` and `docs/evidence/`. The developer report takes precedence over the old gross share-price values in the default evidence. The deck shows a recomputed net price of 0.60 during impairment.','', 'Choose either the phase walk or default arc live. The other uses verified hashes: both cannot fit live into four minutes. Refresh the demo link in `web/public/deck/index.html` when the protocol owner provisions a new vault. No provisioning or transaction is triggered by the deck.','']
for i,s in enumerate(slides):
    title=re.sub('<[^>]*>',' ',s['title']).strip()
    md += [f'## {i+1}. {title} — {s["time"]}', '',s['note'],'','Evidence: '+s['source'],'']
(root/'docs/PITCH-DECK.md').write_text('\n'.join(md))
